using namespace std;

class Solution {
    int memoMin[30][30][30];
    int memoMax[30][30][30];

    pair<int, int> solve(int m, int p1, int p2) {
        if (p1 + p2 == m + 1) return {1, 1};
        if (p1 > p2) swap(p1, p2);
        if (p1 > m - p2 + 1) {
            int np1 = m - p2 + 1, np2 = m - p1 + 1;
            p1 = np1; p2 = np2;
        }
        if (memoMin[m][p1][p2] != 0) return {memoMin[m][p1][p2], memoMax[m][p1][p2]};

        int minR = 100, maxR = 0;
        int p2Mirror = m - p2 + 1;
        int nextM = (m + 1) / 2;

        if (p2 <= (m + 1) / 2) {
            int c1 = p1 - 1, c2 = p2 - p1 - 1;
            for (int i = 0; i <= c1; ++i) {
                for (int j = 0; j <= c2; ++j) {
                    auto res = solve(nextM, i + 1, i + 1 + j + 1);
                    minR = min(minR, 1 + res.first);
                    maxR = max(maxR, 1 + res.second);
                }
            }
        } else {
            int midSurvivors = (p2 - p2Mirror) / 2;
            int c1 = p1 - 1, c2 = p2Mirror - p1 - 1;
            for (int i = 0; i <= c1; ++i) {
                for (int j = 0; j <= c2; ++j) {
                    auto res = solve(nextM, i + 1, i + 1 + j + 1 + midSurvivors);
                    minR = min(minR, 1 + res.first);
                    maxR = max(maxR, 1 + res.second);
                }
            }
        }

        memoMin[m][p1][p2] = minR;
        memoMax[m][p1][p2] = maxR;
        return {minR, maxR};
    }
public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        for (int i = 0; i < 30; ++i)
            for (int j = 0; j < 30; ++j)
                for (int k = 0; k < 30; ++k)
                    memoMin[i][j][k] = memoMax[i][j][k] = 0;

        auto ans = solve(n, firstPlayer, secondPlayer);
        return {ans.first, ans.second};
    }
