class Solution {
    private int[][][] memoMin = new int[30][30][30];
    private int[][][] memoMax = new int[30][30][30];

    private int[] solve(int m, int p1, int p2) {
        if (p1 + p2 == m + 1) return new int[]{1, 1};
        if (p1 > p2) {
            int tmp = p1; p1 = p2; p2 = tmp;
        }
        if (p1 > m - p2 + 1) {
            int np1 = m - p2 + 1, np2 = m - p1 + 1;
            p1 = np1; p2 = np2;
        }
        if (memoMin[m][p1][p2] != 0) return new int[]{memoMin[m][p1][p2], memoMax[m][p1][p2]};

        int minR = 100, maxR = 0;
        int p2Mirror = m - p2 + 1;
        int nextM = (m + 1) / 2;

        if (p2 <= (m + 1) / 2) {
            int c1 = p1 - 1, c2 = p2 - p1 - 1;
            for (int i = 0; i <= c1; ++i) {
                for (int j = 0; j <= c2; ++j) {
                    int[] res = solve(nextM, i + 1, i + 1 + j + 1);
                    minR = Math.min(minR, 1 + res[0]);
                    maxR = Math.max(maxR, 1 + res[1]);
                }
            }
        } else {
            int midSurvivors = (p2 - p2Mirror) / 2;
            int c1 = p1 - 1, c2 = p2Mirror - p1 - 1;
            for (int i = 0; i <= c1; ++i) {
                for (int j = 0; j <= c2; ++j) {
                    int[] res = solve(nextM, i + 1, i + 1 + j + 1 + midSurvivors);
                    minR = Math.min(minR, 1 + res[0]);
                    maxR = Math.max(maxR, 1 + res[1]);
                }
            }
        }

        memoMin[m][p1][p2] = minR;
        memoMax[m][p1][p2] = maxR;
        return new int[]{minR, maxR};
    }

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return solve(n, firstPlayer, secondPlayer);
    }
}

