var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();

    function solve(m, p1, p2) {
        if (p1 + p2 === m + 1) return [1, 1];
        if (p1 > p2) [p1, p2] = [p2, p1];
        if (p1 > m - p2 + 1) {
            const np1 = m - p2 + 1, np2 = m - p1 + 1;
            p1 = np1; p2 = np2;
        }

        const key = `${m},${p1},${p2}`;
        if (memo.has(key)) return memo.get(key);

        let minR = 100, maxR = 0;
        const p2Mirror = m - p2 + 1;
        const nextM = Math.floor((m + 1) / 2);

        if (p2 <= Math.floor((m + 1) / 2)) {
            const c1 = p1 - 1, c2 = p2 - p1 - 1;
            for (let i = 0; i <= c1; ++i) {
                for (let j = 0; j <= c2; ++j) {
                    const [mn, mx] = solve(nextM, i + 1, i + 1 + j + 1);
                    minR = Math.min(minR, 1 + mn);
                    maxR = Math.max(maxR, 1 + mx);
                }
            }
        } else {
            const midSurvivors = Math.floor((p2 - p2Mirror) / 2);
            const c1 = p1 - 1, c2 = p2Mirror - p1 - 1;
            for (let i = 0; i <= c1; ++i) {
                for (let j = 0; j <= c2; ++j) {
                    const [mn, mx] = solve(nextM, i + 1, i + 1 + j + 1 + midSurvivors);
                    minR = Math.min(minR, 1 + mn);
                    maxR = Math.max(maxR, 1 + mx);
                }
            }
        }

        const ans = [minR, maxR];
        memo.set(key, ans);
        return ans;
    }

    return solve(n, firstPlayer, secondPlayer);
};
